        "奶蛙被缩小到池底左侧，暖黄仍能被认出，却不再占据叙事中心。垂下的双手和与身体错开的波心切断了施法的因果关系，它与观者同样只能看见结果。这幅原创构图把时间放进材料：水的运动留下来，水的身体却已撤走。荒诞发生得很轻，仿佛某种过去还在继续，而承受它的东西已经变硬。数字模拟的干性笔触维持着这种不相容，让运动被看见，却无法被顺利解释。"
