        "奶蛙是唯一未被剪断的身体。它看起来已经坐好，双脚却越过椅子照片，悬在另一种平面里；动作的自然与空间的失约同时成立。餐巾也到了，但所有准备没有换来一张共同的桌子。这里的荒诞不靠人物变形，而靠完整的东西无法相聚。数字模拟的纸边、翘角与局部阴影让拼接过程保持可见：把事物贴在一起，并不等于让它们真正处在一起。"
