      "alt": "黄色连续梨形奶蛙坐在黑色长凳上，手持03小票；三张长出黑色细腿的01、02、03号码纸，在黑白叫号窗口前依次排队。",
      "wallText": "拿到号码以后，奶蛙坐下了。01、02、03 则长出腿，替各自的持有人走向窗口。小票仍握在它手里，等待却已经离开身体，自己遵守起了秩序。",
      "interpretation": [
        "三张号码纸从左下向右上排开，号码递减，离窗口最近的是 01。折弯的纸面和齿状下缘仍保留票据的身份，细黑腿却把原本只负责标示顺序的物件，变成了实际执行顺序的身体。",
        "奶蛙握着另一张小小的 03，坐在队列外。大票与小票的对应让替身关系成立：它没有插队，也没有取消等待，而是把站立这项工作交还给号码。那副平静的脸使这次不可能的委托显得完全日常。",
        "右上角的黑色窗口没有服务者。长凳、栏杆与窗口共同维持制度的外形，纸张则认真履行程序。大片留白隔开坐着的角色与移动的票据，让安静和秩序成为两种同时发生的节奏。",
        "黑色墨块、磨损边缘和地面的半调网点，采用数字生成方式模拟印刷。黄色集中在奶蛙身上，奶白腹部、绿色眼圈及橄榄色脚保留角色身份。本作是原创构图，没有引用特定历史原画，也不声称真实印制或官方角色授权。"
      ],
      "epigraph": "我的号码很忙，我先坐一会儿。",
