        "暗蓝桌面上的白粉印痕，与暗红墙和砖炉形成干燥粗粝的背景。奶龙两爪压住杖端，眼睛落在工作区，表情没有被放大成夸张笑脸。这里借用官方角色的大头、短肢与白腹片，将温柔的笨拙放在一次具体的按压里；长面片是构图的夸张，图像并不说明它经历了多少次擀压。"
