        "粉色背景与青绿地带分成两块安静的平面，腔口的深蓝成为最大的暗处。壳内没有画出深层细节，使开口更接近一个难以读完的色形。题名把观看引向聆听的联想；一个小身体面对大空处时所保持的距离，让这块沉静的蓝色有了可供想象的内部。"
