      "wallText": "太阳将天空撑成一整片黄，地面却被蓝紫色的短笔触翻松。奶蛙迈开小步，把手中的几道金黄撒向泥土。它与太阳使用同一种颜色，却只占田野的一小处；向外张开的手，把大画面里的光转成了近处的一次劳动。",
