      "alt": "灰墙左侧黑白奶蛙弯腰双手握扫帚，绿眼望向地面；右侧大黄圆下沿剥落，黄色碎片落在墙脚并堆到扫帚前。",
      "wallText": "扫帚前聚起一小堆黄，墙上的圆也少了一截。奶蛙把碎片拢到脚边，黄昏就从一大片远处的颜色，变成了眼前需要收拾的东西。",
