      "wallText": "持饼臂把圆腹拉成一条斜线，前足站稳，后足以趾端续上最后一点支撑。奶蛙承担了运动员的蓄势，却始终没有把铁饼掷出。圆眼和微笑让用力显得异常轻松，像把比赛最重要的一秒截成了永远不会播放下一帧的表情包。",
