      "wallText": "杯子已经摆好，凳子仍然空着。奶蛙双掌搭在木柜上，暖灯与深蓝窗景把它留在营业和打烊之间。这里没有戏剧性的孤独姿势，只有一个持续可用的位置。像深夜还亮着的聊天窗口：回应的形式都准备好了，下一句话尚未到来。",
