        "布朗库西一九一六年的《吻》提供紧凑体量和环抱关系的启发，奶蛙的圆弧、表情和站姿则是新的处理。这件作品允许荒诞安静下来：两个经常承担梗的角色被赋予近乎纪念物的耐心。和《金色相拥》的繁密相比，亲密在这里通过减少信息出现。它是程序建模的数字石灰岩研究，石纹与柔软触感来自形状、材质和灯光，并非真实手工雕刻的痕迹。"
