      "wallText": "屏幕角落的一条未读，被放大成需要全身托住的红色圆章。奶蛙蹲低、分开双足，橄榄色短爪顶住下缘，脸却仍然平静。数字只有一个，姿势已经像在承担纪念碑。黑色底座把这件微不足道的待办郑重陈列：消息尚未打开，身体先完成了响应。",
